        adviceInstallMenu: 'Tipp: Strom als App installieren — in Chrome oder Edge über das Installationssymbol rechts in der Adressleiste oder im Browsermenü → Strom installieren (Edge: Apps → Diese Website als App installieren). Eine installierte App bekommt meist einen Speicher, den der Browser dauerhaft behält. Ist Strom schon installiert, es besser von dort statt im Tab öffnen — das App-Fenster behält die Daten. Den Stammbaum trotzdem ab und zu in eine Datei speichern.',
        adviceFirefox: 'Firefox fragt, bevor er die Daten einer Website dauerhaft speichert. Das am besten erlauben: Symbol links in der Adressleiste → Berechtigungen → dauerhafter Speicher. Als App installieren kann Firefox Strom nicht; dafür Strom in Chrome oder Edge öffnen und den Stammbaum übertragen (hier exportieren, dort importieren). Den Stammbaum trotzdem ab und zu in eine Datei speichern.',
        adviceMacDock: 'Tipp: Strom ins Dock legen (in Safari: Ablage → Zum Dock hinzufügen). Im Safari-Tab kann Safari die Daten einer Website löschen, wenn sie eine Zeit lang nicht genutzt wird; für die App im Dock gilt diese 7-Tage-Regel nicht. Die App hat aber einen eigenen Speicher — den Stammbaum hier exportieren und dort importieren. Trotzdem in eine Datei speichern.',
        adviceIosSafari: 'Auf iPhone und iPad kann Safari die Daten einer Website löschen, wenn sie eine Zeit lang nicht genutzt wird (Apples 7-Tage-Regel, komplizierter gezählt als nur Tage seit dem letzten Besuch). Tipp: Strom auf den Home-Bildschirm legen (Teilen → Zum Home-Bildschirm) — die App dort unterliegt dieser Regel normalerweise nicht. Die App hat aber einen eigenen Speicher — den Stammbaum hier exportieren und dort importieren. Trotzdem in eine Datei speichern (etwa in iCloud Drive).',
        adviceIosApp: 'iOS garantiert den Speicher auch Apps auf dem Home-Bildschirm nicht — bei Platzmangel kann es ihn leeren. Den Stammbaum ab und zu in eine Datei speichern, am besten in iCloud Drive.',
